- **Always close** as soon as `IsCompletePrefix` holds.
- Use single-token `UnconstrainedStep` outside spans (predictable +1 progress, simpler proof).

// CSD_RATIONALE_BEGIN
// Math word problem CSD revised for gsm_symbolic. Previous attempt timed out
// (200-400s/example) because it spent all 900 maxSteps generating inside
// constrained spans that never produced `=` (loops like `1/2*1/2*1/2*...`).
// Three changes: (a) cap internal budget to ~150 steps so wall clock fits
// the 90s per-example budget; (b) once span has >=3 tokens without an `=`,
// strongly boost `=` via SafeBoostedConstrainedStep so the parser can reach
// a complete prefix; (c) otherwise use SafeRepetitionPenaltyStep to break
// repetitive operator/digit cycles inside the span. Outside spans we use
// single-token UnconstrainedStep for predictable +1 progress accounting and
// to enter a span as soon as the model emits `<<` naturally. Guidance block
// reminds the model of the short `<<a op b=result>>` form and final `####`.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   - Outside UnconstrainedStep branch: insideConstrainedOut becomes true only
//     when next == "<<", at which point currentConstrainedOut := [] which is
//     parser-valid by the method precondition parser.IsValidPrefix([]).
//   - Complete-prefix close branch: CloseConstrainedSpan flips
//     insideConstrainedOut to false and clears currentConstrainedOut, so the
//     implication is vacuous afterwards.
//   - Constrained step else branch: SafeBoostedConstrainedStep and
//     SafeRepetitionPenaltyStep both return EOS or a parser-valid next token
//     (hard mask); EOS path breaks, the non-EOS path goes through
//     AppendConstrainedToken which preserves parser.IsValidPrefix on the
//     extended currentConstrainedOut.
// progress:
//   - Outside branch: steps += 1, |generated| grows by at most 1.
//   - Complete-prefix close branch: steps += 1, |generated| grows by at most 1.
//   - Constrained step branch: steps += 1, AppendConstrainedToken grows
//     |generated| by exactly 1 (or 0 on EOS break).
//   - All branches preserve |generated| <= |generatedPrefix| + steps and the
//     decreases metric `budget - steps` strictly decreases each iteration
//     (every branch either increments steps or breaks).
//   - First-iteration progress (postcondition): if maxSteps > 0 then
//     budget > 0, the loop body runs once and every branch either advances
//     steps to >=1 (so cost > 0) or, in the outside `<<` sub-case, also
//     flips insideConstrainedOut from its initial value, ensuring the
//     state-change postcondition.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(
  lm,
  "Solve briefly step by step. Wrap every arithmetic step in << >>, for example <<3+4=7>> or <<6*5=30>>. Each boxed expression must contain '=' and a numeric result, then close with >>. Keep expressions short. After the final boxed expression, write '#### <number>' on a new line."
);

var budget: nat := if maxSteps > 150 then 150 else maxSteps;
var steps: nat := 0;

while steps < budget
  invariant 0 <= steps <= budget
  invariant budget <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases budget - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if next == "<<" {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedG, closedI, closedC := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedG;
    insideConstrainedOut := closedI;
    currentConstrainedOut := closedC;
    steps := steps + 1;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var eqCount := CSDHelpers.CountTokenOccurrences(currentConstrainedOut, "=");
    var next: Token;
    if eqCount == 0 && |currentConstrainedOut| >= 3 {
      next := helpers.SafeBoostedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, ["="], 8.0, eosToken
      );
    } else {
      next := helpers.SafeRepetitionPenaltyStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, generated, 3.0, eosToken
      );
    }
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    var ag, ai, ac := helpers.AppendConstrainedToken(
      lm, parser, generated, currentConstrainedOut, next
    );
    generated := ag;
    insideConstrainedOut := ai;
    currentConstrainedOut := ac;
  }
}

