// CSD_RATIONALE_BEGIN
// Math word problem CSD revised. Previous attempt: 10% accuracy, 60% syntax.
// Syntax was already above the 44% threshold; the 31pp accuracy gap is
// dominated by semantic_mismatch (16/30 wrong) - the model produces
// well-formed << >> spans but picks the WRONG formula (e.g. emits
// x+y+z+total when the question asks for total-(x+y+z), or
// price*100/(100+brokerage_fee) when the question asks for the difference
// from the budget). Token-level masking cannot fix arithmetic reasoning on
// a 1.5B-Instruct model, so the highest-leverage CSD lever is the
// AppendTaskGuidance block. Three changes vs. attempt 2:
//   1. Rewrite the guidance to explicitly name the operation cues that the
//      failing examples mis-handled ("how much MORE" = subtract; "how many
//      LEFT/REMAINING" = subtract; "how many added/came" = total minus
//      known; "how many TOTAL" = add). This targets the actual failures.
//   2. Stress that the LAST <<...>> must equal the answer to the question
//      and must NOT be followed by more math, so the answer extractor
//      picks up the correct expression.
//   3. Use UnconstrainedChunk outside spans (instead of one-token-at-a-time
//      UnconstrainedStep). Cost is the same in token-steps but it avoids
//      per-token Dafny-side overhead, which helps fit the longer guidance
//      into the 90s/example budget. Inside spans we keep simple
//      ConstrainedStep with the parser hard mask to preserve syntax.
//   4. Raise internal budget from 150 to 300. The previous slowest example
//      was 37s at 150 steps, so 300 steps fit comfortably within 90s, and
//      it gives the longer problems (mode_E partial-span, the unterminated
//      example) room to actually close their spans.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   - Outside branch (UnconstrainedChunk): we only set insideConstrainedOut
//     to true when stoppedOpen holds, and at that point set
//     currentConstrainedOut := [] which is parser-valid by the precondition
//     parser.IsValidPrefix([]). If !stoppedOpen, insideConstrainedOut stays
//     false (state unchanged), keeping the implication vacuous.
//   - Complete-prefix close branch: CloseConstrainedSpan flips
//     insideConstrainedOut to false and clears currentConstrainedOut, so
//     the implication becomes vacuous.
//   - Constrained step branch: ConstrainedStep returns EOS or a parser-valid
//     next token. The EOS path breaks; the non-EOS path goes through
//     AppendConstrainedToken, which extends a valid prefix by a valid token
//     and preserves parser.IsValidPrefix on currentConstrainedOut.
// progress:
//   - Outside (UnconstrainedChunk): by contract, new |generated| <= old
//     |generated| + stepsUsed, and steps grows by exactly stepsUsed, so
//     |generated| <= |generatedPrefix| + steps remains true. The visible
//     token budget consumed equals stepsUsed (EOS counts but is not
//     appended, so visible growth is still <= stepsUsed).
//   - Close branch: appends at most one token, steps += 1.
//   - Constrained step branch: AppendConstrainedToken adds at most one
//     token (or zero on EOS break), steps += 1.
//   - First-iteration postcondition: when maxSteps > 0, budget > 0, the
//     loop runs at least once. Every branch increments steps to >= 1
//     (either via stepsUsed>=1 from the chunk or via the +=1 in the other
//     branches), so cost > 0 after the first iteration.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(
  lm,
  "Grade-school math problem with placeholder variables (price, budget, n1, age1, etc.). Follow this procedure carefully:\n\n1. FIRST read the question's final sentence carefully and identify the operation it asks for:\n   - 'How much MORE' / 'difference' / 'exceeds' / 'over budget' => SUBTRACT (bigger - smaller)\n   - 'How many LEFT' / 'REMAINING' / 'change' after spending => SUBTRACT\n   - 'How many added/came/were bought' to reach a total => total MINUS already-known parts\n   - 'How many TOTAL' / 'altogether' => ADD\n   - 'How many trips/groups' for a capacity => DIVIDE (then round up if needed)\n\n2. Compute one tiny step at a time. Wrap EACH arithmetic step as <<expr=value>>, e.g. <<3+4=7>> or <<50-20=30>>. Use only the variable names that appear in the question (no curly braces).\n\n3. CRITICAL: the VERY LAST <<...>> you write must be the final answer formula to the question. Do NOT continue with more math after it.\n\n4. End with '#### <number>' on a new line.\n\nExample (subtraction question):\nQ: A toy costs $20. With $50, how much change do you get?\nA: Subtract cost from money: <<50-20=30>>.\n#### 30\n\nExample (find missing part):\nQ: There are x apples, y oranges, z pears, and some bananas, total T fruits. How many bananas?\nA: Sum the known fruits <<x+y+z=s>>. Bananas equal the total minus the known: <<T-s=b>>.\n#### b\n\nExample (difference from budget):\nQ: Budget is B, item costs P with fee F% of P. How much OVER budget?\nA: Fee is <<P*F/100=f>>. Total cost is <<P+f=c>>. Amount over budget is <<c-B=d>>.\n#### d\n\nKeep each <<...>> short. The last <<...>> must be the answer."
);

var budget: nat := if maxSteps > 300 then 300 else maxSteps;
var steps: nat := 0;

while steps < budget
  invariant 0 <= steps <= budget
  invariant budget <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases budget - steps
{
  if !insideConstrainedOut {
    var chunkBudget: nat := budget - steps;
    var chunkedG, stoppedOpen, stoppedEos, stepsUsed := helpers.UnconstrainedChunk(
      lm, prompt, generated, chunkBudget, "<<", eosToken
    );
    generated := chunkedG;
    steps := steps + stepsUsed;
    if stoppedEos {
      break;
    }
    if stoppedOpen {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedG, closedI, closedC := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedG;
    insideConstrainedOut := closedI;
    currentConstrainedOut := closedC;
    steps := steps + 1;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    var ag, ai, ac := helpers.AppendConstrainedToken(
      lm, parser, generated, currentConstrainedOut, next
    );
    generated := ag;
    insideConstrainedOut := ai;
    currentConstrainedOut := ac;
  }
}

cost := steps;
